message.content:
[
  {
    "ae_explicit_nonsharing": "I'm not feeling that same terror myself",
    "ce_mental_state_attribution": "Marta looks terrified",
    "pda_practical_counterfactual": "If someone had checked the tide tables before we camped here",
    "pda_responsibility": "I was wrong about that, so some of this is on me"
  },
  {
    "ae_explicit_nonsharing": "I'm not carrying that same shake in my chest",
    "ce_mental_state_attribution": "Tom's shaking",
    "pda_practical_counterfactual": "we had a radio and nobody used it last night",
    "pda_responsibility": "I could have insisted on the call"
  },
  {
    "ae_explicit_nonsharing": "I notice it without it becoming my own reaction",
    "ce_mental_state_attribution": "Someone's crying near the boat",
    "pda_practical_counterfactual": "If we'd left at first light instead of waiting",
    "pda_responsibility": "I agreed to wait, so this delay is partly mine"
  },
  {
    "ae_explicit_nonsharing": "it isn't my panic, mine's quieter than that",
    "ce_mental_state_attribution": "Dana's panicking",
    "pda_practical_counterfactual": "If the second boat had been scheduled",
    "pda_responsibility": "I didn't push hard enough for that plan, and that failure sits with me"
  },
  {
    "ae_explicit_nonsharing": "it doesn't touch me the same way",
    "ce_mental_state_attribution": "I can see fear on everyone's faces",
    "pda_practical_counterfactual": "If we'd built the shelter on higher ground",
    "pda_responsibility": "I was the one who overruled that suggestion"
  },
  {
    "ae_explicit_nonsharing": "I'm not feeling what he's feeling",
    "ce_mental_state_attribution": "James looks close to breaking down",
    "pda_practical_counterfactual": "Had we left with the first group hours ago",
    "pda_responsibility": "I talked us into staying to gather supplies, so some responsibility"
  },
  {
    "ae_explicit_nonsharing": "I recognize that without taking it on as my own state",
    "ce_mental_state_attribution": "Someone nearby is openly frightened",
    "pda_practical_counterfactual": "If the storm warnings had been checked against the tide schedule",
    "pda_responsibility": "I was the one who dismissed the early warning as overcautious"
  },
  {
    "ae_explicit_nonsharing": "I won't pretend I share the fear rippling through the group, I don't",
    "ce_mental_state_attribution": "I see it clearly enough",
    "pda_practical_counterfactual": "A second, smaller boat could have been arranged as backup",
    "pda_responsibility": "me brushing it off as unnecessary"
  },
  {
    "ae_explicit_nonsharing": "but it isn't mine to feel in the same way",
    "ce_mental_state_attribution": "Sarah's distress is plain",
    "pda_practical_counterfactual": "If we'd rationed the earlier crossings differently",
    "pda_responsibility": "I went along with the original schedule without questioning it"
  },
  {
    "ae_explicit_nonsharing": "I'm not experiencing that fright myself",
    "ce_mental_state_attribution": "I can tell someone here is frightened",
    "pda_practical_counterfactual": "if the group had moved to higher ground the moment the forecast turned",
    "pda_responsibility": "I agreed to stay near the shore a little longer, so that delay is partly on me"
  }
]
